import re
def score(program: str) -> float:
    s = re.sub('#.*', ' ', program)
    w = re.findall(r'\w+', s)
    v = 0.01 * len(w) + 0.03 * len(set(w))
    return 1 - 1 / (1 + v)

def score(program: str) -> float:
    n = len(program) or 1
    f = lambda c: program.count(c) / n
    v = sum(w * f(c) for w, c in zip((3.1, 1.7, 2.3, 1.3, 0.7), "(.=:,"))
    return min(1.0, 4 * v)

import re
def score(program: str) -> float:
    s = re.sub(r'\s', '', program)
    w = set(re.findall(r'\w+', program))
    p = sum(not c.isalnum() for c in s) / max(len(s), 1)
    return min(1.0, len(s) / 5000 + len(w) / 150 + p)

